[
    {
        "role": "paragraph",
        "segment": "Static modeling depicts the process by showing that the inputs are transformed to outputs, while dynamic modeling enacts the process so the user can see how intermediate and final products are transformed over time.",
        "citations": [
            {
                "type": "source_text",
                "content": "A static model depicts the process, showing that the inputs are transformed to outputs.A dynamic model enacts the process, so the user can see how intermediate and final products are transformed over time.",
                "img_id": null
            }
        ],
        "type": null
    },
    {
        "role": "paragraph",
        "segment": "Static modeling, exemplified by Lai notation, focuses on the relationships among roles, activities, and artifacts, and state tables show information about the completeness of each artifact at a given time; dynamic modeling, rooted in system dynamics, enables enacting the process and observing resource flows and timing.",
        "citations": [
            {
                "type": "source_text",
                "content": "The process model shows the relationships among the roles, activities, and artifacts, and state tables show information about the completeness of each artifact at a given time.",
                "img_id": null
            },
            {
                "type": "source_text",
                "content": "The systems dynamics approach, introduced by Forrester in the 1950s, has been useful for simulating diverse processes, including ecological, economic, and political systems (Forrester 1991).",
                "img_id": null
            }
        ],
        "type": null
    },
    {
        "role": "paragraph",
        "segment": "Usefulness of static modeling: it clarifies the structure of the process by mapping relationships among roles, activities, and artifacts, helping organize information about the process; use of state tables provides information about artifact completeness at given times.",
        "citations": [
            {
                "type": "source_text",
                "content": "The process model shows the relationships among the roles, activities, and artifacts, and state tables show information about the completeness of each artifact at a given time.",
                "img_id": null
            }
        ],
        "type": null
    },
    {
        "role": "paragraph",
        "segment": "Usefulness of dynamic modeling: it enables simulation and experimentation with the process to observe resource flow and timing, and to evaluate the impact of adding or removing activities and adjusting schedules before actual resources are expended.",
        "citations": [
            {
                "type": "source_text",
                "content": "This dynamic process view enables us  to  simulate  the  process  and  make  changes  before  the  resources  are  actually expended. For example, we can use a dynamic process model to help us decide how many testers we need or when we must initiate testing in order to finish on schedule. Similarly, we can include or exclude activities to see their effects on effort and schedule.",
                "img_id": null
            }
        ],
        "type": null
    }
]

