        ],
        "type": null
    },
    {
        "role": "bullet",
        "segment": "Egoless reviews are those in which remarks focus on the design itself (the process and the product) rather than on who proposed or implemented it.",
        "citations": [
            {
                "type": "source_text",
                "content": "The criticism and discussion during the design review are egoless, because comments are directed at the process and the product, not at the participants.",
                "img_id": null
