[
  {
    "role": "bullet_intro",
    "segment": "System testing vs. integration testing",
    "citations": [
      {
        "type": "source_text",
        "content": "Ideally, after program testing, you can view the collection of components as a single entity. Then, during the first steps of system testing, the integrated collection is evaluated from a variety of perspectives, as previously described.",
        "img_id": null
      }
    ],
    "type": null
  },
  {
    "role": "bullet",
    "segment": "System testing focuses on evaluating the integrated collection as a single entity (the whole system) and can be conducted in phased ways to manage complexity.",
    "citations": [
      {
        "type": "source_text",
        "content": "Ideally, after program testing, you can view the collection of components as a single entity. Then, during the first steps of system testing, the integrated collection is evaluated from a variety of perspectives, as previously described.",
        "img_id": null
      }
    ],
    "type": null
  },
  {
    "role": "bullet",
    "segment": "Integration testing concentrates on how subsystems interact and how integration points work together, often requiring a build or integration plan that defines the subsystems to be tested and describes the testing process.",
    "citations": [
      {
        "type": "source_text",
        "content": "The test team must create a build plan or integration plan to  define  the  subsystems to be tested and to describe how, where, when, and by whom the tests will be conducted.",
        "img_id": null
      }
    ],
    "type": null
  },
  {
    "role": "bullet",
    "segment": "Incremental testing further structures this process by testing subsystems one at a time and planning the sequence of integration to simplify fault localization.",
    "citations": [
      {
        "type": "source_text",
        "content": "Incremental testing requires careful planning. The test team must create a build plan or integration plan to  define  the  subsystems to be tested and to describe how, where, when, and by whom the tests will be conducted.",
        "img_id": null
      }
    ],
    "type": null
  }
]

