[
    {
        "role": "bullet_intro",
        "segment": "Possible tests to expose the Ariane-5 failure causes:",
        "citations": [
            {
                "type": "source_text",
                "content": "The exception was detected, but inappropriately handled because the view had been taken that software should be considered correct until it is shown to be at fault.",
                "img_id": null
            }
        ],
        "type": null
    },
    {
        "role": "bullet",
        "segment": "Regression and failure-handling tests to ensure exceptions are managed correctly and backups are invoked when a fault is detected, rather than assuming software is correct until proven faulty.",
        "citations": [
            {
                "type": "source_text",
                "content": "The exception was detected, but inappropriately handled because the view had been taken that software should be considered correct until it is shown to be at fault.",
                "img_id": null
            },
            {
                "type": "source_text",
                "content": "This means that critical software-in the sense that failure of the software puts the mission at risk-must be identified at a very detailed level, that exceptional behaviour must be confined, and that a reasonable back-up policy must take software failures into account.",
                "img_id": null
            }
        ],
        "type": null
    },
    {
        "role": "bullet",
        "segment": "Tests that validate data integrity and handling of inertial reference system data, by simulating diagnostic or invalid flight data (e.g., a diagnostic bit pattern in place of valid flight data from SRI2) and ensuring the system switches correctly to valid data streams.",
        "citations": [
            {
                "type": "source_text",
                "content": "The SRI2 contained a diagnostic bit pattern that was interpreted erroneously as flight data.",
                "img_id": null
            },
            {
                "type": "source_text",
                "content": "The erroneous data had been declared a failure, and the SRI2 had been shut off. Normally, the on-board computer would have switched to the other inertial reference system, SRI1, but that, too, had been shut down for the same reason.",
                "img_id": null
            }
        ],
        "type": null
    },
    {
        "role": "bullet",
        "segment": "End-to-end integration and lifecycle testing to prevent legacy Ariane-4 assumptions from persisting in Ariane-5 software, ensuring modules that are only relevant pre-launch do not continue executing post-launch.",
        "citations": [
            {
                "type": "source_text",
                "content": "The error occurred in a software module that computed meaningful results only before lift-off.",
                "img_id": null
            },
            {
                "type": "source_text",
                "content": "As soon as the launcher lifted off, the function performed by this module served no useful purpose, so it was no longer needed by the rest of the system.",
                "img_id": null
            },
            {
                "type": "source_text",
                "content": "the module continued its computations for approximately 40 seconds of flight based on a requirement for the Ariane-4 that was not needed for Ariane-5.",
                "img_id": null
            }
        ],
        "type": null
    }
]

